const crypto = require('crypto');
const data = ($input.first().json || {}).query || {};
const secret = $env.AUTH_TOKEN_SECRET || '';
const invoice = String(data.invoice || '').trim();
const company = String(data.company ?? '1').trim();
const action = String(data.action ?? '').trim();
const exp = String(data.exp ?? '').trim();
const sig = String(data.sig || '').trim();
const resend = String(data.resend || '') === '1';
let ok = false, mode = 'invalid';
if (action === 'approve' && exp) {
  const expected = crypto.createHmac('sha256', secret).update(`${company}.${invoice}.approve.${exp}`).digest('base64url');
  ok = sig === expected && Math.floor(Date.now() / 1000) <= Number(exp);
  if (ok) mode = 'v2';
} else if (!action && invoice.length > 0) {
  // legacy link minted before 2026-09-05 (HMAC over invoice number only)
  const legacy = crypto.createHmac('sha256', secret).update(invoice).digest('base64url');
  ok = sig === legacy;
  if (ok) mode = 'legacy';
}
return [{ json: { ok, invoice, company: company || '1', mode, resend, decision: ok ? 'APPROVE' : '' } }];

