/*
 * miniMustache — a dependency-free Mustache subset, embedded verbatim into the
 * n8n invoice-render Code nodes (n8n has no template engine and its sandbox
 * has no module system, so mustache.js's UMD wrapper is a liability here).
 *
 * Supported syntax (exactly what backend/templates/invoice.html uses):
 *   {{name}}        HTML-escaped value from the context stack
 *   {{{name}}}      raw value (no escaping)
 *   {{#key}}...{{/key}}  section: array -> loop (empty array renders nothing),
 *                        truthy -> render once with the value pushed,
 *                        falsy/missing (0, '', null, undefined) -> skip
 *   {{^key}}...{{/key}}  inverted section: renders only when the value is
 *                        falsy or an empty array
 * Names may use dotted paths (a.b.c). Unknown names render as ''.
 *
 * Node test harness: `node backend/templates/mustache_mini.test.js`
 * (exports via CommonJS when available; a plain function otherwise).
 */
function miniMustache(template, data) {
  // HTML comments never reach the output — and this template's own header
  // comment documents the syntax with literal {{...}} examples, so they must
  // not be tokenized.
  template = String(template).replace(/<!--[\s\S]*?-->/g, '');

  // Escape map built without literal entity text in the source.
  const AMP = String.fromCharCode(38);
  const ENT = {
    [String.fromCharCode(38)]: AMP + 'amp;',
    [String.fromCharCode(60)]: AMP + 'lt;',
    [String.fromCharCode(62)]: AMP + 'gt;',
    [String.fromCharCode(34)]: AMP + 'quot;',
    [String.fromCharCode(39)]: AMP + '#39;',
  };
  function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, (c) => ENT[c]);
  }

  function lookup(stack, name) {
    const parts = name.split('.');
    for (let i = stack.length - 1; i >= 0; i--) {
      let v = stack[i];
      let ok = true;
      for (const p of parts) {
        if (v == null || typeof v !== 'object' || !(p in v)) { ok = false; break; }
        v = v[p];
      }
      if (ok) return v;
    }
    return undefined;
  }

  function isTruthy(v) {
    if (Array.isArray(v)) return v.length > 0;
    return Boolean(v);
  }

  // tokenize: walk the template, producing text / tag tokens
  const tokens = [];
  let i = 0;
  while (i < template.length) {
    const open = template.indexOf('{{', i);
    if (open === -1) { tokens.push({ t: 'text', v: template.slice(i) }); break; }
    if (open > i) tokens.push({ t: 'text', v: template.slice(i, open) });
    let raw = false, inner;
    if (template.slice(open, open + 3) === '{{{') {
      const close = template.indexOf('}}}', open + 3);
      if (close === -1) throw new Error('unterminated {{{ in template');
      inner = template.slice(open + 3, close);
      raw = true;
      i = close + 3;
    } else {
      const close = template.indexOf('}}', open + 2);
      if (close === -1) throw new Error('unterminated {{ in template');
      inner = template.slice(open + 2, close);
      i = close + 2;
    }
    const m = inner.match(/^\s*(#|\^|\/)?\s*([\w.]+)\s*$/);
    if (!m) throw new Error('bad tag: ' + inner);
    tokens.push({ t: m[1] || 'var', name: m[2], raw: raw });
  }

  // parse into a tree (sections nest)
  function parse(start, end) {
    const nodes = [];
    let i = start;
    while (i < end) {
      const tok = tokens[i];
      if (tok.t === 'text' || tok.t === 'var') { nodes.push(tok); i++; continue; }
      if (tok.t === '/') throw new Error('unexpected {{/' + tok.name + '}}');
      const close = tokens.findIndex((t, j) => j > i && t.t === '/' && t.name === tok.name);
      if (close === -1 || close >= end) throw new Error('unclosed section {{' + tok.t + tok.name + '}}');
      nodes.push({ t: tok.t, name: tok.name, body: parse(i + 1, close) });
      i = close + 1;
    }
    return nodes;
  }
  const tree = parse(0, tokens.length);

  function renderNodes(nodes, stack) {
    let out = '';
    for (const n of nodes) {
      if (n.t === 'text') { out += n.v; continue; }
      const v = lookup(stack, n.name);
      if (n.t === 'var') {
        const s = v == null ? '' : v;
        out += n.raw ? String(s) : escapeHtml(s);
      } else if (n.t === '#') {
        if (Array.isArray(v)) {
          for (const item of v) out += renderNodes(n.body, stack.concat([item]));
        } else if (isTruthy(v)) {
          out += renderNodes(n.body, stack.concat([v]));
        }
      } else if (n.t === '^') {
        if (!isTruthy(v)) out += renderNodes(n.body, stack);
      }
    }
    return out;
  }

  return renderNodes(tree, [data]);
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { render: miniMustache };
}

const INVOICE_TEMPLATE = "<!doctype html>\n<!--\n  INVOICE LAYOUT TEMPLATE \u2014 the single source of truth for what an invoice\n  looks like (the house rule: Render Invoice HTML in the gateway and the\n  approve-side fallback copy are BOTH generated from this file; never edit\n  them by hand). Format: Mustache (mustache.js, embedded by the patch script).\n\n  Data sources for each placeholder:\n    company_*      -> company_profile row (branding, addresses, GST/PST reg,\n                      payment_instructions) \u2014 per-company, multi-tenant ready\n    logo_data_uri  -> company_profile (logo_data + logo_content_type), built\n                      by the renderer as data:<type>;base64,<bytes> \u2014 so the\n                      archived invoice HTML is SELF-CONTAINED (an issued\n                      invoice never depends on an externally linked image).\n                      Empty = text-only header, the layout holds without it.\n    invoice_*      -> invoices row (number, type, dates, amounts, holdback)\n    bill_to_*      -> customer + structured bill-to address on the invoice\n    line_items     -> invoice_line_items rows (contract line / change orders),\n                      one table row each\n    holdback       -> invoices.holdback_amount + the dynamic holdback label\n    *_amount       -> always computed in SQL before rendering, never here\n\n  Mustache notes: sections are the list itself ({{#line_items}}), {{^name}}\n  is the \"unless\" branch. PDF remains print-to-PDF from this HTML\n  (@media print) \u2014 no server-side PDF engine.\n-->\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<title>Invoice {{invoice_number}} \u2014 {{company_name}}</title>\n<style>\n  :root {\n    --brand: {{brand_primary_color}};\n    --ink: #0f172a;\n    --muted: #64748b;\n    --line: #e2e8f0;\n  }\n  * { box-sizing: border-box; }\n  body { font-family: -apple-system, 'Segoe UI', Roboto, Arial, sans-serif; color: var(--ink); margin: 0; }\n  .page { max-width: 800px; margin: 24px auto; padding: 32px 40px; }\n\n  header { display:flex; justify-content:space-between; align-items:flex-start;\n           border-bottom: 4px solid var(--brand); padding-bottom: 18px; }\n  .co { display: flex; align-items: center; gap: 16px; }\n  .logo { height: 56px; width: auto; border: 1px solid var(--line); border-radius: 8px;\n          padding: 4px; background: #fff; flex: none; }\n  .co h1 { font-size: 22px; margin: 0 0 4px; color: var(--brand); letter-spacing: .4px; }\n  .co p  { margin: 2px 0; color: var(--muted); font-size: 12px; line-height: 1.5; }\n  .doc { text-align: right; }\n  .doc .label { font-size: 26px; font-weight: 700; letter-spacing: 4px; }\n  .doc .num   { color: var(--brand); font-weight: 600; font-size: 15px; margin-top: 2px; }\n\n  .meta { display: flex; justify-content: space-between; gap: 32px; margin: 24px 0 6px; }\n  .meta h3 { font-size: 11px; text-transform: uppercase; letter-spacing: 1.2px;\n             color: var(--muted); margin: 0 0 6px; }\n  .meta p  { margin: 2px 0; font-size: 13px; line-height: 1.55; }\n  .meta .val { font-weight: 600; }\n\n  table.items { width: 100%; border-collapse: collapse; margin-top: 14px; }\n  .items th { text-align: left; font-size: 11px; text-transform: uppercase;\n              letter-spacing: 1.2px; color: var(--muted);\n              border-bottom: 2px solid var(--ink); padding: 8px 10px; }\n  .items td { padding: 12px 10px; font-size: 14px; border-bottom: 1px solid var(--line); }\n  .items .amt { text-align: right; white-space: nowrap; }\n\n  .totals { margin-left: auto; width: 320px; margin-top: 14px; }\n  .totals .row { display: flex; justify-content: space-between;\n                 padding: 6px 12px; font-size: 14px; }\n  .totals .row.grand { background: var(--brand); color: #fff; font-weight: 700;\n                       margin-top: 6px; border-radius: 3px; }\n  .totals .row.holdback { color: var(--muted); font-size: 13px; }\n\n  .pay { margin-top: 22px; background: #f1f5f9; border-left: 4px solid var(--brand);\n         padding: 14px 16px; font-size: 13px; line-height: 1.6; }\n  .pay strong { display: block; font-size: 11px; text-transform: uppercase;\n                letter-spacing: 1.2px; color: var(--muted); margin-bottom: 4px; }\n\n  footer { margin-top: 30px; border-top: 1px solid var(--line); padding-top: 12px;\n           font-size: 11px; color: var(--muted); text-align: center; line-height: 1.6; }\n\n  @media print {\n    .page { margin: 0; max-width: none; padding: 0; }\n    body { -webkit-print-color-adjust: exact; print-color-adjust: exact; }\n  }\n</style>\n</head>\n<body>\n<div class=\"page\">\n\n  <header>\n    <div class=\"co\">\n      {{#logo_data_uri}}\n      <img class=\"logo\" src=\"{{logo_data_uri}}\" alt=\"{{company_name}} logo\">\n      {{/logo_data_uri}}\n      <div class=\"id\">\n        <h1>{{company_name}}</h1>\n        <p>{{company_address}}<br>\n           {{company_phone}}{{#gst_reg_line}}<br>\n           {{{gst_reg_line}}}{{/gst_reg_line}}</p>\n      </div>\n    </div>\n    <div class=\"doc\">\n      <div class=\"label\">INVOICE</div>\n      <div class=\"num\">{{invoice_number}}</div>\n    </div>\n  </header>\n\n  <div class=\"meta\">\n    <div>\n      <h3>Bill To</h3>\n      <p><span class=\"val\">{{bill_to_name}}</span>{{#bill_to_address}}<br>\n         {{{bill_to_address}}}{{/bill_to_address}}</p>\n      <h3 style=\"margin-top:14px\">Project</h3>\n      <p>{{project_name}}</p>\n    </div>\n    <div style=\"text-align:right\">\n      <h3>Details</h3>\n      <p>Invoice date&nbsp;&nbsp;<span class=\"val\">{{issued_date}}</span><br>\n         Due date&nbsp;&nbsp;<span class=\"val\">{{due_date}}</span><br>\n         Type&nbsp;&nbsp;<span class=\"val\">{{invoice_type_label}}</span></p>\n    </div>\n  </div>\n\n  <table class=\"items\">\n    <tr><th style=\"width:32px\">#</th><th>Description</th><th class=\"amt\">Amount</th></tr>\n    {{#line_items}}\n    <tr><td>{{position}}</td>\n        <td>{{description}}</td>\n        <td class=\"amt\">{{amount}}</td></tr>\n    {{/line_items}}\n  </table>\n\n  <div class=\"totals\">\n    <div class=\"row\"><span>Subtotal</span><span>{{net_amount}}</span></div>\n    {{#gst_amount}}\n    <div class=\"row\"><span>{{gst_label}}</span><span>{{gst_amount}}</span></div>\n    {{/gst_amount}}\n    {{#pst_amount}}\n    <div class=\"row\"><span>{{pst_label}}</span><span>{{pst_amount}}</span></div>\n    {{/pst_amount}}\n    {{^pst_amount}}\n    <div class=\"row\"><span>PST</span><span>Not applicable</span></div>\n    {{/pst_amount}}\n    <div class=\"row grand\"><span>Total due</span><span>{{amount_due}}</span></div>\n    {{#holdback_amount}}\n    <div class=\"row holdback\"><span>{{holdback_label}}: {{holdback_amount}}</span></div>\n    {{/holdback_amount}}\n  </div>\n\n  {{#payment_instructions}}\n  <div class=\"pay\">\n    <strong>Payment instructions</strong>\n    {{{payment_instructions}}}\n  </div>\n  {{/payment_instructions}}\n\n  <footer>\n    {{company_name}} &bull; {{company_address}} &bull; {{company_phone}}<br>\n    Thank you for your business.\n  </footer>\n\n</div>\n</body>\n</html>\n";

function buildInvoiceData(inv) {
  const money = (v) => Number(v ?? 0).toLocaleString('en-CA', { style: 'currency', currency: 'CAD' });
  const typeMap = { 'DEPOSIT': 'Deposit', 'PROGRESS_BILLING': 'Progress billing',
                    'CHANGE_ORDER': 'Change order', 'FINAL': 'Final',
                    'Deposit': 'Deposit', 'Progress': 'Progress billing',
                    'Change Order': 'Change order', 'Final': 'Final' };
  const typeLabel = typeMap[inv?.invoice_type] || inv?.invoice_type || '';
  const addressLine = [inv?.street_address, inv?.city,
                       `${inv?.province ?? ''} ${inv?.postal_code ?? ''}`]
    .filter(Boolean).join(', ');
  const taxBits = [];
  if (inv?.gst_reg_number) taxBits.push('GST # ' + inv.gst_reg_number);
  if (inv?.pst_reg_number) taxBits.push('PST # ' + inv.pst_reg_number);
  const lines = Array.isArray(inv?.lines) ? inv.lines : [];
  const pct = inv?.billing_percentage;
  const basis = inv?.billed_basis;
  const isOriginalBasis = pct != null && basis != null && inv?.contract_original != null &&
    Math.abs(Number(basis) - Number(inv.contract_original)) < 0.005;
  const basisLabel = isOriginalBasis ? 'contract value' : 'revised contract value';
  const lineLabel = inv?.description
    ? String(inv.description)
    : (pct != null && basis != null)
      ? `${typeLabel} \u2014 ${String(Number(pct))}% of ${basisLabel} (${money(basis)})`
      : typeLabel || 'Services';
  const billTo = [inv?.bill_street, inv?.bill_city,
                  inv?.bill_province ? `${inv?.bill_province} ${inv?.bill_postal ?? ''}` : inv?.bill_postal]
    .map(s => (s || '').toString().trim()).filter(Boolean).join('<br>');
  const holdbackPct = inv?.retention_rate != null
    ? Math.round(Number(inv.retention_rate) * 100) : 10;
  const items = lines.length
    ? lines.map((l, i) => ({ position: i + 1, description: l.description || '',
                             amount: money(l.amount) }))
    : [{ position: 1, description: lineLabel, amount: money(inv?.net_amount) }];
  const payLines = (inv?.payment_instructions || '').split('\n')
    .filter(s => s.trim().length > 0);
  return {
    brand_primary_color: inv?.brand_primary_color ?? '#1a3a5c',
    company_name: inv?.company_name ?? 'Ireh Construction',
    company_address: addressLine,
    company_phone: inv?.phone ?? '',
    gst_reg_line: taxBits.join('<br>'),
    // The logo is baked in as a data: URI — an archived invoice never
    // depends on an externally linked image.
    logo_data_uri: inv?.logo_data && inv?.logo_content_type
      ? `data:${inv.logo_content_type};base64,${inv.logo_data}` : '',
    invoice_number: inv?.invoice_number ?? '',
    issued_date: inv?.issued_date ?? '',
    due_date: inv?.due_date ?? '',
    invoice_type_label: typeLabel,
    project_name: inv?.project_name ?? '',
    bill_to_name: (inv?.customer_name ?? '') +
                  (inv?.customer_company ? ' (' + inv.customer_company + ')' : ''),
    bill_to_address: billTo,
    line_items: items,
    net_amount: money(inv?.net_amount),
    gst_label: 'GST',
    gst_amount: Number(inv?.gst_amount) ? money(inv.gst_amount) : 0,
    pst_label: 'PST',
    pst_amount: Number(inv?.pst_amount) ? money(inv.pst_amount) : 0,
    amount_due: money(inv?.amount_due),
    holdback_amount: Number(inv?.holdback_amount) ? money(inv.holdback_amount) : '',
    holdback_label: `Holdback (${holdbackPct}% retained)`,
    payment_instructions: payLines.join('<br>'),
  };
}
const html = miniMustache(INVOICE_TEMPLATE, buildInvoiceData(inv));
return [{ json: { ...inv, html } }];

const row = $('Lookup Invoice').first().json;
const num = row?.invoice_number ?? '';
const email = row?.email ?? '';
const resent = row?.email_sent_at ? ' (resent)' : '';
const html = `<html><body style="font-family:Helvetica,Arial,sans-serif;margin:2rem;color:#1e293b"><h1 style="color:#16a34a">Invoice sent${resent}</h1><p>Invoice <strong>${num}</strong> was emailed to <strong>${email}</strong>.</p><p>You can close this page.</p></body></html>`;
