const q = ($('approve-invoice').first().json || {}).query || {};
const row = $input.first()?.json || {};
const when = row?.email_sent_at ? ' on ' + String(row.email_sent_at).slice(0, 10) : '';
const base = row?.portal_base_url || 'https://n8n2.ordrnow.com';
const params = new URLSearchParams();
['invoice', 'company', 'exp', 'action', 'sig'].forEach((k) => { if (q[k]) params.set(k, String(q[k])); });
params.set('resend', '1');
const resendUrl = `${base}/webhook/approve-invoice?${params.toString()}`;
const html = `<html><body style="font-family:Helvetica,Arial,sans-serif;margin:2rem;color:#1e293b"><h1 style="color:#d97706">Already sent</h1><p>Invoice <strong>${row?.invoice_number ?? ''}</strong> was already emailed to <strong>${row?.email ?? ''}</strong>${when}.</p><p>If the client did not receive it, you can send it again:</p><p><a href="${resendUrl}" style="display:inline-block;background:#16a34a;color:#fff;padding:.6rem 1.2rem;border-radius:6px;text-decoration:none">Send this invoice again</a></p></body></html>`;
return [{ json: { html } }];

const crypto = require('crypto');
const data = ($input.first().json || {}).query || {};
const secret = $env.AUTH_TOKEN_SECRET || '';
const invoice = String(data.invoice || '').trim();
const company = String(data.company ?? '1').trim();
const action = String(data.action ?? '').trim();
const exp = String(data.exp ?? '').trim();
const sig = String(data.sig || '').trim();
let ok = false, mode = 'invalid';
if (action === 'reject' && exp) {
  const expected = crypto.createHmac('sha256', secret).update(`${company}.${invoice}.reject.${exp}`).digest('base64url');
  ok = sig === expected && Math.floor(Date.now() / 1000) <= Number(exp);
  if (ok) mode = 'v2';
}
return [{ json: { ok, invoice, company: company || '1', mode, decision: ok ? 'REJECT' : '' } }];

